import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第61章 河灯","description":"","frontmatter":{},"headers":[],"relativePath":"第61章_河灯.md","filePath":"第61章_河灯.md"}'),r={name:"第61章_河灯.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第61章-河灯" tabindex="-1">第三卷 潮汐 · 第61章 河灯 <a class="header-anchor" href="#第三卷-潮汐-·-第61章-河灯" aria-label="Permalink to &quot;第三卷 潮汐 · 第61章 河灯&quot;">​</a></h1><p>寒假里，雾先漫过南雾县的河堤。</p><p>我到河边时，江苒已蹲在石阶上。她抱着浅口纸盒，盖子掀开一角，露出挤挨的纸星星。风过，星角碰着盒壁，响起很细的碎声，像指尖划过纸面。</p><p>“数过了吗。”我问。</p><p>她抬头，眼被路灯照亮，鼻尖冻红。“数过了，加上你口袋那颗，正好二十二颗，一颗不多，一颗不少。”</p><p>我摸摸口袋。那颗粉蓝的星是她清早塞的，折得很鼓，棱角抵着布料。她说这颗压轴，等水稳再放，要我捂热了亲手放。</p><p>河面宽，水流慢。对岸灯火隔着雾，像浮着的碎金，一晃一晃。空气有水草凉腥，还有甜香。堤口支着一排纸灯，透出暖黄光。顾远他妈裹着厚围巾坐在灯后头看着，见我们来，笑眯了眼。</p><p>“阿婆，生意好吗。”江苒凑过去，声音甜。</p><p>顾远他妈往我们手心各塞一颗糖。“好，放灯人多。这糖海盐味，含着暖，手就不僵了。”</p><p>糖纸窸窣。我剥开含住，先咸后甜，奶香在舌尖化开，心口也松些。江苒也含一颗，腮帮鼓起小包。</p><p>林小满从堤上跑下，举两盏河灯，发髻跑歪。“快，水位正好，晚了风大，烛就站不稳。”</p><p>灯是莲花形，底稳，中间插好烛粒。陈默跟在后，抱旧布包，装火柴和备用烛粒，还有小卷纸巾。他走小心，鞋踩青苔出轻响，怕惊了雾。</p><p>“顾远呢。”我问。</p><p>“下游占位置。”林小满指远处，雾里有人影晃，“那水缓，灯飘得远，能看很久。”</p><p>我们沿石阶下走。青苔滑，江苒伸手扶我一把。她手指凉，指尖沾纸粉，蹭我袖口，留下淡白印。她自己也没站稳，晃一下，被我反手扶住。</p><p>顾远占了最好一段，把外套铺石阶招呼我们坐。何晓已坐在那，抱旧录音机，磁带转着，传出很轻歌声，混着水声，听不真切，却让人心软。磁带有些年头，偶尔卡顿，沙沙空转一截又接上。</p><p>“叶老师说别玩晚。”何晓小声说，眼亮亮，“她巡完教室过来看看，让我们靠里站。”</p><p>“知道。”江苒笑，把纸盒抱紧，“放完就回，保证不踩水。”</p><p>我把纸盒放膝头往外拿。江苒把星摆进灯，很讲究，每盏几颗，什么色相配，都想一会。指尖捏星角转来转去，就着灯光比颜色。</p><p>“这盏三颗浅黄，像碎月亮。”她把星围烛台摆圈，留出空隙透光。</p><p>“这盏湖蓝配粉，多嫩。”林小满拿起藕粉的比划，爱不释手。</p><p>陈默只管点火。火柴擦着，火苗窜起，被风吹歪又稳住。他用手拢火，等烛稳才松手。火光照他脸，睫毛投下小影。他动作慢而稳，像怕烫着灯纸。</p><p>第一盏下水时，人都安静。</p><p>我蹲水边，手伸进水。水冰刺骨，指尖瞬间发麻，凉顺腕往上爬。灯底触水面，晃两下稳住。烛光映水，晕开暖。三颗星浮灯边，打旋散开，像小船离岸。</p><p>“走了。”江苒轻声说，声落风里。</p><p>灯顺水前飘。雾低，光在雾里走，像有人提小灯散步，越走越远，影拉长。</p><p>第二盏第三盏接连下水。每盏下去，人群低呼。河面渐布光点，远近错落，像星掉进河。水波推它们，时聚时散，煞是好看。</p><p>秦浩和赵晴也来了。秦浩拿包海盐糖见人就发，糖纸剥得哗响。赵晴剥一颗塞江苒，又塞我一颗，自己也含一颗。</p><p>“含着，甜，暖。”她说，腮鼓起。</p><p>江苒含糖，冲我笑得含糊。“你也吃，别苦脸，今晚是甜的。”</p><p>我盯水面。风大些，烛晃。我紧张，怕灯翻，怕星散，更怕她失望。她为这夜准备许久，指尖都折出薄茧。</p><p>“别怕。”江苒肩碰我，暖意透过衣料，“翻了再放，星多，火柴也多。”</p><p>她往灯放透明纸折的星。烛光透过星角，折碎光落她手背，像薄霜。她皮肤白，血管透淡青。我闻她发丝皂香，混河水凉气，呼吸轻落耳边，有点痒。</p><p>“沈聿。”她叫我。</p><p>“嗯。”</p><p>“记得为何二十二颗吗。”她拨星角，认真看我。</p><p>记得。高一秋天，我们教室后排折星。那天阴雨，窗外潮气重，纸软总塌。我们边折边数，数到第二十二颗，窗外忽放晴，一线光落桌，正照星堆，亮晃眼。她当时说，这么亮，以后每年放一次，把坏运飘走，把好运留下。</p><p>“记得。”我说，“把光留住，把暖留住。”</p><p>她笑弯眼，映烛火。“对，把光留住。你记性好。”</p><p>风忽紧。河面起纹，灯群晃，两盏碰一起打转又分开。众人低呼又松气。水声大些，拍石阶哗哗响。</p><p>林小满抓陈默袖，指尖白。“别翻，千万别翻。”</p><p>陈默拍她手背，声稳。“不会，底稳，浪小，放心。”</p><p>顾远起身往上游走几步挡风。他个高，影落水面像堤。他张开外套，护住我们这片，风果然小些。他头发被吹乱，也不理。</p><p>“好点吗。”他问，声散风里。</p><p>“好多了。”何晓把录音机调大。旧歌清晰些，嗓音温柔，唱潮起潮落，唱远行人早回。</p><p>江苒把头靠我肩，轻一下又直起，怕人看见。她把最后灯推我面前，很郑重，像托付。</p><p>“这盏，你来。”她说。</p><p>灯空着。她把盒倒过来，只剩几颗，一颗颗数给我看，数慢。</p><p>“六颗，加你口袋那颗，七颗。这盏最大，多放，显得富。”</p><p>“都放。”我问。</p><p>“嗯，这是我们的。”她看我眼亮，烛光跳里面，“别人三四颗，我们多放，心诚，光才大。”</p><p>我笑出声，肩松。从口袋掏粉蓝星，放掌心捂暖。星纸被体温暖，棱角抵掌心，疼却踏实。我捏了又捏，舍不得放。</p><p>我把七颗一颗颗放进，粉蓝放中间，被众星拱着。烛点，透明先亮，接着湖蓝藕粉，一层层晕开。整灯像捧小银河，暖晃眼。水汽扑脸，凉带腥甜。</p><p>我端灯到水边。江苒身侧挡风，衣角贴腿。我手抖，不知冷是紧张。她蹲下扶我腕，腕暖了些。</p><p>“慢点，让底吃水，别急。”她说。</p><p>我照做。灯底触水，凉顺指尖爬。我松手，灯浮住。七颗围烛，挤挨随波晃，像不愿散的鱼。</p><p>好稳。我心里松口气。</p><p>我蹲看它走。它走慢，像舍不得离。我们影落水，被染暖，头挨头。糖在嘴里化尽，只剩咸香。</p><p>“河上有多少灯。”江苒问，声飘。</p><p>我抬头。灯火点点，星浮沉，根本数不清。雾把远光揉团，分不清哪灯哪星哪倒影。风裹歌声糖香，一阵一阵。</p><p>“数不清。”我说，“太多太亮。”</p><p>“记住感觉。”她把手伸水拨一下，“记住水凉，风轻，糖甜，歌软。”</p><p>涟漪散开，推灯前走一截。她指尖冻红，缩回直抖，水珠顺指滴。我握她手，两只凉手握一起，反觉安心，凉意淡了。</p><p>身后脚步响。叶老师披厚外套，提袋热饮分大家，热气雾里明显。她站堤上看会，声柔带笑。</p><p>“真好看。”她说，“明年还来吗。”</p><p>“来。”林小满大声举手，“明年折更多，放更远。”</p><p>众笑。笑落雾软散，被水声接住，传远。</p><p>我们灯飘远，混进群，再分不清哪盏。江苒仍盯，脖仰酸也不动，像能认出那团银河。</p><p>“沈聿。”她压低声只我们听见，带潮气，“潮水把星带走，明年拿什么许愿。”</p><p>我顺她目光看。河心雾浓，灯火明灭，水打旋，几盏挤一起，晃厉害。雾深处像有东西浮沉。</p><p>光影中，我们那盏忽晃一下，烛歪向边，眼碰水面，七颗散开，那颗粉蓝的，正往下沉，晕开一圈粉蓝。</p>',71)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
